"""Self-contained numpy model for dd2_pb17_17_lin5_9_nw (generated by mk_dd_candidate.py).

Construction (matches directed_design/gen_verilog.py):
  round i: x = LIN_i(P(SBOX_i(x ^ rk_i)))
  LIN_i(x) = x ^ rotl64(x,a) ^ rotl64(x,b)  (a,b per round: (5, 9))
  P: out[P[i]] = in[i]
  rk_i = rotl64(key, 13*(i+1)) ^ RC[i]
"""
import numpy as np

SBOX_ROUNDS = [[0, 1, 2, 3, 4, 6, 8, 11, 13, 9, 7, 15, 12, 10, 5, 14], [0, 1, 2, 3, 4, 6, 8, 11, 13, 9, 7, 15, 12, 10, 5, 14], [0, 1, 2, 3, 4, 6, 8, 11, 13, 9, 7, 15, 12, 10, 5, 14], [0, 1, 2, 3, 4, 6, 8, 11, 13, 9, 7, 15, 12, 10, 5, 14]]
PBOX = [17, 34, 51, 4, 21, 38, 55, 8, 25, 42, 59, 12, 29, 46, 63, 16, 33, 50, 3, 20, 37, 54, 7, 24, 41, 58, 11, 28, 45, 62, 15, 32, 49, 2, 19, 36, 53, 6, 23, 40, 57, 10, 27, 44, 61, 14, 31, 48, 1, 18, 35, 52, 5, 22, 39, 56, 9, 26, 43, 60, 13, 30, 47, 0]
RC = np.array([11400714819323198485, 4354685564936845354, 15755400384260043839, 8709371129873690708], dtype=np.uint64)
M64 = np.uint64(0xFFFFFFFFFFFFFFFF)
ROUNDS = 4
ROTS = [5, 9]


def _rots(r):
    if isinstance(ROTS[0], (list, tuple)):
        return ROTS[r][0], ROTS[r][1]
    return ROTS[0], ROTS[1]


def _rotl(x, r):
    r %= 64
    if r == 0:
        return x
    return ((x << np.uint64(r)) | (x >> np.uint64(64 - r))) & M64


def _sbox64(x, r):
    sb = np.array(SBOX_ROUNDS[r], dtype=np.uint64)
    y = np.zeros_like(x)
    for i in range(16):
        y |= sb[((x >> np.uint64(4 * i)) & np.uint64(0xF))] << np.uint64(4 * i)
    return y & M64


def _pbox64(x):
    y = np.zeros_like(x)
    for i in range(64):
        y |= ((x >> np.uint64(i)) & np.uint64(1)) << np.uint64(PBOX[i])
    return y & M64


def _lin(x, r):
    a, b = _rots(r)
    return (x ^ _rotl(x, a) ^ _rotl(x, b)) & M64


def _round(x, key, i):
    rk = _rotl(key, 13 * (i + 1)) ^ RC[i]
    return _lin(_pbox64(_sbox64(x ^ rk, i)), i)


def mix_np(V, K):
    x = np.asarray(V, dtype=np.uint64)
    k = np.asarray(K, dtype=np.uint64)
    for i in range(ROUNDS):
        x = _round(x, k, i)
    return x & M64


def mix(v, k):
    return int(mix_np(np.uint64(v), np.uint64(k)))
